const H = this.helpers;
const SUPA = '__SUPABASE_URL__';
const SR = '__SUPABASE_SERVICE_KEY__';
const CONFIRM = '__CONFIRM_TOKEN__';
const sH = { apikey: SR, Authorization: 'Bearer ' + SR };

// 1. Find Shakti's scheduled campaigns (Broadcast Send sends from Shakti's number only; another club's
//    campaign is left as it is instead of being stuck at 'sending')
let due = [], TID = null;
try {
  const tr = await H.httpRequest({ method: 'GET', url: SUPA + '/rest/v1/tenants?slug=eq.shakti&select=id', headers: sH, json: true });
  TID = Array.isArray(tr) && tr[0] ? tr[0].id : null;
  if (!TID) return [{ json: { error: 'tenant shakti not found' } }];
  const url = SUPA + '/rest/v1/broadcasts?status=eq.scheduled&tenant_id=eq.' + TID + '&select=id,title,template_name,body,created_at';
  const rows = await H.httpRequest({ method: 'GET', url, headers: sH, json: true });
  if (Array.isArray(rows)) {
    const now = new Date();
    for (const r of rows) {
      let cfg = {};
      try { cfg = JSON.parse(r.body || '{}'); } catch(e) {}
      const schedAt = cfg.schedule_at || (cfg.segment && cfg.segment.schedule_at);
      if (schedAt && new Date(schedAt) <= now) {
        due.push({ id: r.id, title: r.title, template_name: r.template_name, cfg });
      }
    }
  }
} catch(e) {
  return [{ json: { error: 'Failed to query scheduled broadcasts: ' + (e.message || e) } }];
}

/* 1b. No scheduled campaign due: continue ONE long campaign that is waiting for its next batch (Broadcast Send
   sends at most ~120 recipients per run and saves its progress on the row; the page continues it while open,
   this tick continues it when the page has gone quiet for 90 s and no other run holds its lease). */
if (!due.length) {
  let waiting = [];
  try {
    const rows = await H.httpRequest({ method: 'GET', url: SUPA + '/rest/v1/broadcasts?status=eq.sending&tenant_id=eq.' + TID + '&select=id,title,body', headers: sH, json: true });
    const now = Date.now();
    for (const r of (Array.isArray(rows) ? rows : [])) {
      let cfg = {}; try { cfg = JSON.parse(r.body || '{}'); } catch (e) {}
      const p = cfg.progress; if (!p || !(Number(p.done) < Number(p.total))) continue;
      const lease = p.lease_until ? new Date(p.lease_until).getTime() : 0;
      const quiet = now - (p.next_at ? new Date(p.next_at).getTime() : 0);
      if (lease > now || quiet < 90 * 1000) continue;
      waiting.push({ id: r.id, title: r.title, cfg, quiet });
    }
  } catch (e) {}
  if (!waiting.length) return [{ json: { status: 'No scheduled campaigns due', checked_at: new Date().toISOString() } }];
  waiting.sort((a, b) => b.quiet - a.quiet);
  const item = waiting[0];
  try {
    const res = await H.httpRequest({ method: 'POST', url: 'https://n8n.example.com/webhook/broadcast-send',
      headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ tenant: (item.cfg && item.cfg.tenant) || 'shakti', confirm: CONFIRM, broadcast_id: item.id, dry_run: false, resume: true }), json: true });
    if (!res || res.ok !== true) {
      /* a refusal that is not "busy": note it on the row; after 3 such ticks the campaign is marked failed with the reason */
      if (!(res && res.busy)) {
        const errs = Number((item.cfg.progress && item.cfg.progress.resume_errors) || 0) + 1;
        const why = String((res && res.error) || 'Broadcast Send gave no answer').slice(0, 300);
        if (errs >= 3) await markFailed(item.id, item.cfg, 'could not continue the campaign: ' + why);
        else { item.cfg.progress.resume_errors = errs; item.cfg.last_error = why;
          try { await H.httpRequest({ method: 'PATCH', url: SUPA + '/rest/v1/broadcasts?id=eq.' + item.id + '&status=eq.sending', headers: { ...sH, 'Content-Type': 'application/json', Prefer: 'return=minimal' }, body: JSON.stringify({ body: JSON.stringify(item.cfg) }) }); } catch (e) {} }
      }
      return [{ json: { checked_at: new Date().toISOString(), resumed: item.title, ok: false, res } }];
    }
    return [{ json: { checked_at: new Date().toISOString(), resumed: item.title, ok: true, partial: !!res.partial, done: res.done, remaining: res.remaining } }];
  } catch (e) {
    return [{ json: { checked_at: new Date().toISOString(), resumed: item.title, ok: false, error: String(e.message || e).slice(0, 200) } }];
  }
}

// 2. Dispatch each due campaign via broadcast-send webhook
const dueAt = (cfg) => cfg.schedule_at || (cfg.segment && cfg.segment.schedule_at);
/* only while it is still 'sending': a campaign Broadcast Send has already marked 'sent' is never overwritten */
const markFailed = async (id, cfg, why) => {
  try {
    await H.httpRequest({
      method: 'PATCH',
      url: SUPA + '/rest/v1/broadcasts?id=eq.' + id + '&status=eq.sending',
      headers: { ...sH, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
      body: JSON.stringify({ status: 'failed', body: JSON.stringify(Object.assign({}, cfg, { last_error: why, failed_at: new Date().toISOString() })) })
    });
  } catch (err) {}
};
const results = [];
/* one campaign per tick: a dispatch can take ~200 s and this run must end before the server's 300 s limit */
for (const item of due.slice(0, 1)) {
  // Claim it: only the run that moves it from 'scheduled' to 'sending' dispatches it, so overlapping runs never
  // send it twice. sent_at is cleared: Broadcast Send sets it once when it takes the campaign.
  try {
    const claimed = await H.httpRequest({
      method: 'PATCH',
      url: SUPA + '/rest/v1/broadcasts?id=eq.' + item.id + '&status=eq.scheduled',
      headers: { ...sH, 'Content-Type': 'application/json', Prefer: 'return=representation' },
      body: JSON.stringify({ status: 'sending', sent_at: null }),
      json: true
    });
    const row = Array.isArray(claimed) ? claimed[0] : null;
    if (!row) { results.push({ id: item.id, title: item.title, ok: true, skipped: 'taken by another run or changed' }); continue; }
    try { item.cfg = JSON.parse(row.body || '{}'); } catch (e) { item.cfg = {}; }
    const at = dueAt(item.cfg);
    if (!at || new Date(at) > new Date()) {
      // staff moved it to a later time a moment ago: put it back
      await H.httpRequest({
        method: 'PATCH',
        url: SUPA + '/rest/v1/broadcasts?id=eq.' + item.id + '&status=eq.sending',
        headers: { ...sH, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
        body: JSON.stringify({ status: 'scheduled' })
      });
      results.push({ id: item.id, title: item.title, ok: true, skipped: 'rescheduled' });
      continue;
    }
  } catch (e) {
    results.push({ id: item.id, title: item.title, ok: false, error: 'could not claim it: ' + (e.message || e) });
    continue;
  }
  try {
    const payload = {
      tenant: (item.cfg && item.cfg.tenant) || 'shakti', /* as on live since 2026-09-17 */
      confirm: CONFIRM,
      broadcast_id: item.id,
      dry_run: false,
      template: item.cfg.template || item.template_name,
      language: item.cfg.language || 'en',
      image_url: item.cfg.image_url || null,
      vars: item.cfg.vars || {},
      custom_recipients: item.cfg.custom_recipients || undefined,
      segment: item.cfg.segment || undefined
    };

    const res = await H.httpRequest({
      method: 'POST',
      url: 'https://n8n.example.com/webhook/broadcast-send',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
      json: true
    });

    // Broadcast Send answers 200 even when it refuses: then the campaign is 'failed', with its reason for staff
    if (!res || res.ok !== true) {
      const why = String((res && (res.error || (res.errors && res.errors[0]))) || 'Broadcast Send gave no answer').slice(0, 300);
      await markFailed(item.id, item.cfg, why);
      results.push({ id: item.id, title: item.title, ok: false, error: why });
      continue;
    }
    results.push({ id: item.id, title: item.title, ok: true, res });
  } catch(e) {
    // Mark failed
    await markFailed(item.id, item.cfg, 'dispatch failed: ' + String(e.message || e).slice(0, 200));
    results.push({ id: item.id, title: item.title, ok: false, error: e.message || e });
  }
}

return [{ json: { checked_at: new Date().toISOString(), processed: results.length, results } }];
